// Command gen-dtmf-vectors synthesizes the pinned ITU-T Q.23 DTMF test vectors
// under testdata/dtmf.
//
// WHY IT EXISTS AND WHY IT DUPLICATES THE SINE MATH. The governing spec pins
// testdata/dtmf/q23-16digit-<twist>db.pcm as the fixture the Goertzel detector
// is graded against, but the repository shipped only a .gitkeep and external
// fixtures cannot be fetched in this environment. Synthesizing them from the
// Q.23 parameters is therefore the only way to have them at all. This program
// deliberately does NOT import internal/media/codec: a vector generated by the
// very code under test cannot falsify that code, so the generator carries its
// own independent implementation of the tone pairs and the sine sum.
//
// Output format: raw PCM, 8000 Hz, mono, signed 16-bit little-endian, no
// header. Each file holds the 16 digits in the order 0123456789ABCD*# — one
// 100 ms dual tone followed by 100 ms of digital silence per digit.
//
// Twist is the high-tone-to-low-tone amplitude ratio in dB; the filename suffix
// spells the sign (p/m) because a literal + or - in a path is awkward.
//
// Run: make dtmf-vectors
package main

import (
	"encoding/binary"
	"fmt"
	"math"
	"os"
	"path/filepath"
)

const (
	sampleRate = 8000.0
	toneMs     = 100
	silenceMs  = 100
	// baseAmp leaves headroom so the summed pair never clips even at the
	// widest twist this generator produces (±8 dB). render() splits the
	// twist symmetrically about baseAmp (high tone x10^(twist/40), low tone
	// x10^(-twist/40)), so at ±8 dB the peak sum is:
	// 6000 * (10^(8/40) + 10^(-8/40)) = 6000 * (1.585 + 0.631) = 6000 * 2.216
	// ≈ 13295 < 32767.
	baseAmp = 6000.0
)

// digits is the emission order; it MUST match codec.DTMFAlphabet so the
// detector test can assert the decoded string equals the alphabet itself.
const digits = "0123456789ABCD*#"

// lowFor/highFor are ITU-T Q.23's tone pairs, restated independently of
// internal/media/codec (see the package comment).
func freqsFor(d byte) (low, high float64) {
	lows := [4]float64{697, 770, 852, 941}
	highs := [4]float64{1209, 1336, 1477, 1633}
	grid := map[byte][2]int{
		'1': {0, 0}, '2': {0, 1}, '3': {0, 2}, 'A': {0, 3},
		'4': {1, 0}, '5': {1, 1}, '6': {1, 2}, 'B': {1, 3},
		'7': {2, 0}, '8': {2, 1}, '9': {2, 2}, 'C': {2, 3},
		'*': {3, 0}, '0': {3, 1}, '#': {3, 2}, 'D': {3, 3},
	}
	rc, ok := grid[d]
	if !ok {
		panic(fmt.Sprintf("gen-dtmf-vectors: %q is not a DTMF digit", d))
	}
	return lows[rc[0]], highs[rc[1]]
}

func render(twistDB float64) []int16 {
	// Split the twist symmetrically about baseAmp so total power is comparable
	// across files: the high tone gains half the twist, the low tone loses half.
	highAmp := baseAmp * math.Pow(10, twistDB/40)
	lowAmp := baseAmp * math.Pow(10, -twistDB/40)

	toneN := int(toneMs * sampleRate / 1000)
	silenceN := int(silenceMs * sampleRate / 1000)
	out := make([]int16, 0, len(digits)*(toneN+silenceN))
	for i := 0; i < len(digits); i++ {
		low, high := freqsFor(digits[i])
		for n := 0; n < toneN; n++ {
			t := float64(n) / sampleRate
			v := lowAmp*math.Sin(2*math.Pi*low*t) + highAmp*math.Sin(2*math.Pi*high*t)
			out = append(out, int16(math.Round(v)))
		}
		out = append(out, make([]int16, silenceN)...)
	}
	return out
}

func write(path string, pcm []int16) error {
	buf := make([]byte, len(pcm)*2)
	for i, s := range pcm {
		binary.LittleEndian.PutUint16(buf[2*i:], uint16(s))
	}
	return os.WriteFile(path, buf, 0o644)
}

func main() {
	dir := filepath.Join("testdata", "dtmf")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	cases := []struct {
		suffix string
		twist  float64
	}{
		{"0db", 0}, {"p4db", 4}, {"m4db", -4}, {"p8db", 8}, {"m8db", -8},
	}
	for _, c := range cases {
		path := filepath.Join(dir, "q23-16digit-"+c.suffix+".pcm")
		if err := write(path, render(c.twist)); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		fmt.Println("wrote", path)
	}
}
